  private static double ReadOpacity(Dictionary<string,object> saved,string key,double fallback){try{var raw=Json.Get(saved,key);double value=raw==null?fallback:Convert.ToDouble(raw);return double.IsNaN(value)||double.IsInfinity(value)?fallback:Math.Max(.1,Math.Min(1,value));}catch{return fallback;}}
  private void SetHovered(bool value){hovered=value;if(headerTools!=null)headerTools.Visibility=value?Visibility.Visible:Visibility.Hidden;ApplyOpacity();}
  private void ApplyOpacity(){if(surface==null)return;double target=hovered?hoverAlpha:idleAlpha;if(Math.Abs(surface.Opacity-target)<.001)return;double from=surface.Opacity;surface.BeginAnimation(UIElement.OpacityProperty,null);surface.Opacity=target;if(IsLoaded)surface.BeginAnimation(UIElement.OpacityProperty,new System.Windows.Media.Animation.DoubleAnimation(from,target,TimeSpan.FromMilliseconds(160)){FillBehavior=System.Windows.Media.Animation.FillBehavior.Stop});}
