  private Button Hover(string value){return new Button{Content=value,Style=(Style)FindResource("HoverPill"),FontFamily=new FontFamily("Malgun Gothic")};}
  private void Item(string name,Action action){var item=new MenuItem{Header=name};item.Click+=(s,e)=>action();menu.Items.Add(item);}
  private static string ValidColor(string value,string fallback){try{var c=Parse(value);return string.Format("#{0:X2}{1:X2}{2:X2}",c.R,c.G,c.B);}catch{return fallback;}}
  private void OnChanged(){if(!Dispatcher.HasShutdownStarted)Dispatcher.BeginInvoke(new Action(Render));}
  private void Toggle(){if(busy)return;if(client.Session==null){startAfterLogin=true;OpenSettings("login");return;}if(client.Pending!=null||client.Snapshot==null){Operate(async()=>{if(client.Snapshot==null)await client.Restore();else await client.Retry();});return;}Operate(()=>client.Command(mainAction,null));}
  private async void Operate(Func<Task> action){if(busy)return;busy=true;message="";Render();try{await action();}catch(ApiError e){message=e.Message;}catch{message="연결을 확인한 뒤 다시 시도해 주세요. 저장 요청은 보관됩니다.";}finally{busy=false;Render();}}
  private void ClockOut(){if(!busy&&client.Session!=null&&client.Pending==null&&client.Snapshot!=null&&!string.IsNullOrEmpty(Json.Text(Json.Map(client.Snapshot,"state"),"segmentId")))Operate(()=>client.Command("clockOut",null));}
  private void HideToTray(){Save();SetHovered(false);Hide();}
  private void Logout(){if(busy||client.Pending!=null){message="저장 결과를 확인한 뒤 로그아웃해 주세요.";return;}client.Logout();message="";Render();}
