  private async void OpenDashboard(){if(dashboardOpening)return;dashboardOpening=true;try{string url=await client.DashboardLink();Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}catch{Dispatcher.Invoke(new Action(()=>{message="대시보드 로그인을 연결하지 못했습니다. 잠시 후 다시 열어 주세요.";Render();}));}finally{dashboardOpening=false;}}
  private void ShowPanel(){Show();SetHovered(IsMouseOver);}
  private string Token(string key){var bg=Parse(color);string selected=theme=="custom"?(bg.R*.299+bg.G*.587+bg.B*.114>150?"cream":"dark"):theme;return Json.Text(Json.Map(themes,selected),key);}
  private void Save(){if(!IsLoaded)return;client.Store.Save("panel",new{left=(int)Left,top=(int)Top,pinned=Topmost,theme=theme,color=color,text=ink,opacity=hoverAlpha,opacityIdle=idleAlpha,opacityHover=hoverAlpha,autoText=autoText,showStatus=showStatus,showRest=showRest,showTitle=showTitle});}
  private void Quit(){Save();exiting=true;if(preferences!=null)preferences.Close();Close();Application.Current.Shutdown();}
  private void TryDelete(string name){try{File.Delete(Path.Combine(profile,name));}catch{}}
  private void Atomic(string name,object data){string p=Path.Combine(profile,name);File.WriteAllText(p+".tmp",Json.Write(data),new System.Text.UTF8Encoding(false));if(File.Exists(p))File.Replace(p+".tmp",p,null);else File.Move(p+".tmp",p);}
  private bool QA(){return Environment.GetEnvironmentVariable("WORKLOG_QA_CAPTURE")=="1"&&System.Text.RegularExpressions.Regex.IsMatch(Json.Text(client.Session,"email"),"^qa-[a-f0-9-]{36}@worklog\\.test$");}
  private void WriteStatus(){var state=Json.Map(client.Snapshot,"state");Atomic("instance.json",new{product="WorklogScripts",version=ReleaseVersion(),pid=Process.GetCurrentProcess().Id,root=root,ready=true});Atomic("status.json",new{product="WorklogScripts",version=ReleaseVersion(),ready=true,pid=Process.GetCurrentProcess().Id,revision=Json.Number(state,"revision"),status=Json.Text(state,"status"),signedIn=client.Session!=null,busy=busy,toolWindow=(GetWindowLong(new WindowInteropHelper(this).Handle,-20)&0x80)!=0,appWindow=(GetWindowLong(new WindowInteropHelper(this).Handle,-20)&0x40000)!=0,visible=IsVisible,updatedAt=Client.UtcNow(),width=ActualWidth,height=ActualHeight,timer=clock.Text,restTimer=restClock,workMs=workValue,goalMs=Json.Number(state,"dailyGoalMs"),progress=progress,timelineWork=workBars,timelineRest=restBars,action=mainAction,extra=extra.Text,theme=theme,color=color,text=ink,numberFont=clock.FontFamily.Source,settingsVisible=preferences!=null&&preferences.IsVisible,startupPromptVisible=StartupRegistration.Visible,opacity=surface.Opacity,opacityIdle=idleAlpha,opacityHover=hoverAlpha,hovered=hovered,firstStart=firstStart,afterWork=afterWork,clockOutVisible=clockOut.IsVisible,quitVisible=quitButton.IsVisible});
   string capture=Json.Number(state,"revision")+theme+color+idleAlpha+hoverAlpha+hovered+firstStart+extra.Text+restClock;if(QA()&&captured!=capture&&Math.Abs(surface.Opacity-(hovered?hoverAlpha:idleAlpha))<.002){UpdateLayout();var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap((int)Math.Ceiling(ActualWidth),(int)Math.Ceiling(ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(this);var png=new System.Windows.Media.Imaging.PngBitmapEncoder();png.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(profile,"qa-panel.png")))png.Save(file);captured=capture;}
