  private void ReadCommands(){foreach(string path in Directory.GetFiles(Path.Combine(profile,"commands"),"*.json")){Dictionary<string,object> c=null;try{c=Json.Read(File.ReadAllText(path));}finally{File.Delete(path);}if(Math.Abs(Client.UtcNow()-Json.Number(c,"createdAt"))>30000)continue;switch(Json.Text(c,"action")){case "show":ShowPanel();break;case "settings":Settings();break;case "theme":string selected=Json.Text(c,"theme");if(selected=="cream"||selected=="dark"){Settings();qaTheme(selected);}break;case "stop":Quit();return;case "refresh":Operate(()=>client.Refresh());break;case "qa-toggle":if(QA())toggle.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));break;case "qa-welcome":if(QA()&&firstStart)welcome.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));break;case "qa-hover":if(QA())RaiseEvent(new MouseEventArgs(Mouse.PrimaryDevice,Environment.TickCount){RoutedEvent=Json.Get(c,"over") as bool? == true?Mouse.MouseEnterEvent:Mouse.MouseLeaveEvent});break;case "qa-opacity":if(QA()){Settings();qaSetOpacity(Convert.ToDouble(Json.Get(c,"idle")),Convert.ToDouble(Json.Get(c,"hover")));}break;case "qa-style":if(QA()){Settings();qaCustomize();}break;case "qa-theme":if(QA()){Settings();qaTheme(Json.Text(c,"theme"));}break;case "qa-default":if(QA()){Settings();qaDefaults();}break;case "qa-goal":if(QA()){Settings();qaSetGoal(Json.Get(c,"goalMs")==null?(long?)null:Json.Number(c,"goalMs"));}break;case "qa-finish":if(QA())finish.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));break;}}}
  private double progress; private long workValue;
  private void DrawTimeline(Dictionary<string,object> day,long work,long goal){
   var rows=Json.Rows(day,"segments").Where(x=>Json.Get(x,"deletedAt")==null).OrderBy(x=>Json.Number(x,"start")).ToList();
   var keep=new HashSet<string>(rows.Select(x=>Json.Text(x,"id")));foreach(string id in timelineBars.Keys.Where(x=>!keep.Contains(x)).ToList())timelineBars.Remove(id);
   double total=rows.Sum(x=>(double)Math.Max(0,(Json.Get(x,"end")==null?client.Now:Json.Number(x,"end"))-Json.Number(x,"start")));progress=goal>0?Math.Min(1,work/(double)goal):rows.Count>0?1:0;double width=Math.Max(0,timeline.ActualWidth),cursor=0;timeline.Clip=new RectangleGeometry(new Rect(0,0,width,4),2,2);
   var fallback=rows.FirstOrDefault(x=>Json.Get(x,"end")==null)??rows.FirstOrDefault();
   foreach(var s in rows){long length=Math.Max(0,(Json.Get(s,"end")==null?client.Now:Json.Number(s,"end"))-Json.Number(s,"start"));double fraction=total>0?length/total*progress:ReferenceEquals(s,fallback)?progress:0;double left=cursor*width;cursor+=fraction;if(fraction<=0)continue;bool rest=Json.Text(s,"kind")=="break";if(rest)restBars++;else workBars++;string id=Json.Text(s,"id");System.Windows.Shapes.Rectangle bar;if(!timelineBars.TryGetValue(id,out bar)){bar=new System.Windows.Shapes.Rectangle{Height=4};timelineBars[id]=bar;}bar.Width=Math.Max(0,Math.Min(width-left,fraction*width));bar.Fill=new SolidColorBrush(Parse(Token(rest?"rest":"work")));bar.ToolTip=(rest?"휴식":"업무")+" · "+Duration(length,true)+(Json.Text(s,"title")==""?"":" · "+Json.Text(s,"title"));Canvas.SetLeft(bar,left);timeline.Children.Add(bar);}
