 internal sealed class WidgetGlyph:FrameworkElement {
  private readonly string kind;private Brush ink;
  public WidgetGlyph(string value){kind=value;Width=Height=16;IsHitTestVisible=false;}
  public void Set(Color color){ink=new SolidColorBrush(color);InvalidateVisual();}
  protected override void OnRender(DrawingContext dc){if(ink==null)return;dc.PushTransform(new ScaleTransform(ActualWidth/16,ActualHeight/16));var pen=new Pen(ink,1.6){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round};if(kind=="finish")dc.DrawRoundedRectangle(ink,null,new Rect(3,3,10,10),2,2);else if(kind=="hide"||kind=="close"){double edge=kind=="close"?3:4;dc.DrawLine(pen,new Point(edge,edge),new Point(16-edge,16-edge));dc.DrawLine(pen,new Point(16-edge,edge),new Point(edge,16-edge));}else if(kind=="exit"){dc.DrawGeometry(null,pen,Geometry.Parse("M 4,3.5 A 5.5,5.5 0 1 0 12,3.5"));dc.DrawLine(pen,new Point(8,1),new Point(8,7));}else{for(int i=0;i<8;i++){double a=i*Math.PI/4;dc.DrawLine(pen,new Point(8+5*Math.Cos(a),8+5*Math.Sin(a)),new Point(8+7*Math.Cos(a),8+7*Math.Sin(a)));}dc.DrawEllipse(null,pen,new Point(8,8),4.5,4.5);dc.DrawEllipse(null,pen,new Point(8,8),1.5,1.5);}dc.Pop();}
 }
 internal sealed class ToggleGlyph:FrameworkElement {
  private bool paused,busy;private Color color;private Brush ink;
  private static readonly Geometry triangle=Geometry.Parse("M 4,1.8 Q 3,1.2 3,2.5 L 3,13.5 Q 3,14.8 4.2,14.1 L 14,8.8 Q 15.2,8 14,7.2 Z");
  public ToggleGlyph(){Width=16;Height=16;IsHitTestVisible=false;}
  public void Set(bool p,bool b,Color c){if(ink!=null&&paused==p&&busy==b&&color==c)return;paused=p;busy=b;color=c;ink=new SolidColorBrush(c);InvalidateVisual();}
  protected override void OnRender(DrawingContext dc){if(ink==null)return;if(busy){for(int i=0;i<3;i++)dc.DrawEllipse(ink,null,new Point(3+i*5,8),1.5,1.5);}else if(paused){dc.DrawRoundedRectangle(ink,null,new Rect(3,1.5,4,13),2,2);dc.DrawRoundedRectangle(ink,null,new Rect(10,1.5,4,13),2,2);}else dc.DrawGeometry(ink,null,triangle);}
 }
